// Package profile is the canonical reader for v7 benchmark profile YAML files
// under scripts/benchmark/profiles/. The schema is frozen by SD-010 §3
// (Harness × Model Matrix Benchmark); additive fields require a spec amendment.
package profile

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"gopkg.in/yaml.v3"
)

// ProviderType enumerates the four provider client paths supported by the
// matrix runner. SD-010 §3 forbids silent override; the adapter selects its
// client path by exact match on this field.
type ProviderType string

const (
	ProviderAnthropic    ProviderType = "anthropic"
	ProviderOpenAI       ProviderType = "openai"
	ProviderOpenAICompat ProviderType = "openai-compat"
	ProviderOpenRouter   ProviderType = "openrouter"
	ProviderOMLX         ProviderType = "omlx"
	ProviderLMStudio     ProviderType = "lmstudio"
	ProviderOllama       ProviderType = "ollama"
	ProviderGoogle       ProviderType = "google"
)

func (p ProviderType) valid() bool {
	switch p {
	case ProviderAnthropic, ProviderOpenAI, ProviderOpenAICompat, ProviderOpenRouter,
		ProviderOMLX, ProviderLMStudio, ProviderOllama, ProviderGoogle:
		return true
	}
	return false
}

// Provider describes how the harness adapter should reach the model API.
type Provider struct {
	Type      ProviderType `yaml:"type"`
	Model     string       `yaml:"model"`
	BaseURL   string       `yaml:"base_url"`
	APIKeyEnv string       `yaml:"api_key_env"`
}

// Pricing is the single source of truth for cost reconciliation. Units are
// USD per million tokens.
type Pricing struct {
	InputUSDPerMTok       float64 `yaml:"input_usd_per_mtok"`
	OutputUSDPerMTok      float64 `yaml:"output_usd_per_mtok"`
	CachedInputUSDPerMTok float64 `yaml:"cached_input_usd_per_mtok"`
}

// Limits captures provider-side ceilings. rate_limit_* are informational in
// v1 (D6 forbids concurrency > 1) and reserved for the follow-up scheduler.
type Limits struct {
	MaxOutputTokens int `yaml:"max_output_tokens"`
	ContextTokens   int `yaml:"context_tokens"`
	RateLimitRPM    int `yaml:"rate_limit_rpm"`
	RateLimitTPM    int `yaml:"rate_limit_tpm"`
}

// Sampling is opaque to the runner; passed verbatim to the adapter's
// apply_profile step. Reasoning is a free-form string ("low" | "medium" |
// "high" | "" depending on the family). Pointer fields are omitted when
// nil so server defaults apply.
type Sampling struct {
	Temperature float64  `yaml:"temperature"`
	Reasoning   string   `yaml:"reasoning,omitempty"`
	TopP        *float64 `yaml:"top_p,omitempty"`
	TopK        *int     `yaml:"top_k,omitempty"`
	MinP        *float64 `yaml:"min_p,omitempty"`
}

// ModelServerInfo is populated at run time by querying the local model server
// (e.g. lmstudio /api/v0/models/<id>). Fields are empty/zero when the server
// does not expose them.
type ModelServerInfo struct {
	Quantization        string `json:"quantization,omitempty"`
	LoadedContextLength int    `json:"loaded_context_length,omitempty"`
	MaxContextLength    int    `json:"max_context_length,omitempty"`
	Source              string `json:"source,omitempty"` // URL queried
}

// Versioning records when the profile was authored and which provider
// snapshot the adapter resolved at apply_profile time.
type Versioning struct {
	ResolvedAt string `yaml:"resolved_at"`
	Snapshot   string `yaml:"snapshot"`
}

// Profile is the in-memory shape of a frozen v1 profile YAML.
type Profile struct {
	ID         string     `yaml:"id"`
	Provider   Provider   `yaml:"provider"`
	Pricing    Pricing    `yaml:"pricing"`
	Limits     Limits     `yaml:"limits"`
	Sampling   Sampling   `yaml:"sampling"`
	Versioning Versioning `yaml:"versioning"`

	// Path is the filesystem path the profile was loaded from. Not part of
	// the YAML; populated by Load / LoadDir for diagnostics and `profiles
	// list` output.
	Path string `yaml:"-"`
}

// Load reads and validates a single profile YAML file at path.
func Load(path string) (*Profile, error) {
	raw, err := os.ReadFile(path) // #nosec G304 -- path is an operator-supplied profile location, scoped by Validate()
	if err != nil {
		return nil, fmt.Errorf("read profile %s: %w", path, err)
	}
	var p Profile
	dec := yaml.NewDecoder(strings.NewReader(string(raw)))
	dec.KnownFields(true)
	if err := dec.Decode(&p); err != nil {
		return nil, fmt.Errorf("parse profile %s: %w", path, err)
	}
	p.Path = path
	if err := p.Validate(); err != nil {
		return nil, fmt.Errorf("validate profile %s: %w", path, err)
	}
	return &p, nil
}

// LoadDir loads every *.yaml / *.yml file under dir, sorted by id. It is the
// entry point used by `fiz-bench profiles list`.
func LoadDir(dir string) ([]*Profile, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, fmt.Errorf("read profiles dir %s: %w", dir, err)
	}
	var profiles []*Profile
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		ext := strings.ToLower(filepath.Ext(e.Name()))
		if ext != ".yaml" && ext != ".yml" {
			continue
		}
		p, err := Load(filepath.Join(dir, e.Name()))
		if err != nil {
			return nil, err
		}
		profiles = append(profiles, p)
	}
	sort.Slice(profiles, func(i, j int) bool { return profiles[i].ID < profiles[j].ID })
	return profiles, nil
}

// Validate checks that every required v1 field is present. The schema is
// frozen by SD-010 §3; missing fields are a hard error rather than a warning.
func (p *Profile) Validate() error {
	if strings.TrimSpace(p.ID) == "" {
		return fmt.Errorf("id is required")
	}
	if !p.Provider.Type.valid() {
		return fmt.Errorf("provider.type %q is not one of anthropic|openai|openrouter|omlx|lmstudio|ollama|google", p.Provider.Type)
	}
	if strings.TrimSpace(p.Provider.Model) == "" {
		return fmt.Errorf("provider.model is required")
	}
	if strings.TrimSpace(p.Provider.BaseURL) == "" {
		return fmt.Errorf("provider.base_url is required")
	}
	if strings.TrimSpace(p.Provider.APIKeyEnv) == "" {
		return fmt.Errorf("provider.api_key_env is required")
	}
	if p.Pricing.InputUSDPerMTok < 0 || p.Pricing.OutputUSDPerMTok < 0 || p.Pricing.CachedInputUSDPerMTok < 0 {
		return fmt.Errorf("pricing.* must be non-negative")
	}
	if p.Limits.MaxOutputTokens <= 0 {
		return fmt.Errorf("limits.max_output_tokens must be > 0")
	}
	if p.Limits.ContextTokens <= 0 {
		return fmt.Errorf("limits.context_tokens must be > 0")
	}
	if strings.TrimSpace(p.Versioning.ResolvedAt) == "" {
		return fmt.Errorf("versioning.resolved_at is required")
	}
	return nil
}

package profile

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/require"
)

func writeFile(path string, data []byte) error {
	return os.WriteFile(path, data, 0o644)
}

// repoProfilesDir returns the path to scripts/benchmark/profiles/ relative
// to this test file (internal/benchmark/profile/). Three levels up.
func repoProfilesDir(t *testing.T) string {
	t.Helper()
	return filepath.Join("..", "..", "..", "scripts", "benchmark", "profiles")
}

func TestLoadDir_AllShippedProfilesValidate(t *testing.T) {
	profiles, err := LoadDir(repoProfilesDir(t))
	require.NoError(t, err)
	require.NotEmpty(t, profiles, "expected at least one shipped profile")

	ids := map[string]*Profile{}
	for _, p := range profiles {
		require.NoError(t, p.Validate(), "profile %s failed validation", p.ID)
		ids[p.ID] = p
	}

	// SD-010 §3 + bead AC: smoke + noop fixtures must ship in v1.
	require.Contains(t, ids, "smoke")
	require.Contains(t, ids, "noop")
	// Phase A.1 anchor: gpt-5-mini via OpenRouter.
	require.Contains(t, ids, "gpt-5-mini")
}

func TestLoad_GPT5MiniAnchorProfile(t *testing.T) {
	p, err := Load(filepath.Join(repoProfilesDir(t), "gpt-5-mini.yaml"))
	require.NoError(t, err)
	require.Equal(t, "gpt-5-mini", p.ID)
	require.Equal(t, ProviderOpenAICompat, p.Provider.Type)
	require.Equal(t, "openai/gpt-5-mini", p.Provider.Model)
	require.Equal(t, "OPENROUTER_API_KEY", p.Provider.APIKeyEnv)
	// Census §5 pricing snapshot — values must stay inside the ≤ $3/Mtok
	// output bracket that selected this row.
	require.Equal(t, 2.00, p.Pricing.OutputUSDPerMTok)
	require.Equal(t, 0.25, p.Pricing.InputUSDPerMTok)
	require.Equal(t, 0.05, p.Pricing.CachedInputUSDPerMTok)
	require.LessOrEqual(t, p.Pricing.OutputUSDPerMTok, 3.00)
	require.Equal(t, 16384, p.Limits.MaxOutputTokens)
	require.Greater(t, p.Limits.ContextTokens, 0)
	require.Greater(t, p.Limits.RateLimitRPM, 0)
	require.Greater(t, p.Limits.RateLimitTPM, 0)
	require.Equal(t, "medium", p.Sampling.Reasoning)
	require.Equal(t, "2026-04-30", p.Versioning.ResolvedAt)
	require.NotEmpty(t, p.Versioning.Snapshot)
}

func TestLoad_SmokeProfileFields(t *testing.T) {
	p, err := Load(filepath.Join(repoProfilesDir(t), "smoke.yaml"))
	require.NoError(t, err)
	require.Equal(t, "smoke", p.ID)
	require.Equal(t, ProviderOpenAICompat, p.Provider.Type)
	require.Equal(t, "OPENAI_API_KEY", p.Provider.APIKeyEnv)
	require.Greater(t, p.Limits.MaxOutputTokens, 0)
	require.Greater(t, p.Limits.ContextTokens, 0)
	require.NotEmpty(t, p.Versioning.ResolvedAt)
	require.NotEmpty(t, p.Path)
}

func TestLoad_NoopProfileFields(t *testing.T) {
	p, err := Load(filepath.Join(repoProfilesDir(t), "noop.yaml"))
	require.NoError(t, err)
	require.Equal(t, "noop", p.ID)
	require.Equal(t, ProviderOpenAICompat, p.Provider.Type)
	require.Equal(t, 0.0, p.Pricing.InputUSDPerMTok)
	require.Equal(t, "noop-fixture", p.Versioning.Snapshot)
}

func TestValidate_RejectsMissingFields(t *testing.T) {
	cases := []struct {
		name    string
		mutate  func(p *Profile)
		wantSub string
	}{
		{"missing id", func(p *Profile) { p.ID = "" }, "id is required"},
		{"bad provider type", func(p *Profile) { p.Provider.Type = "bedrock" }, "provider.type"},
		{"missing model", func(p *Profile) { p.Provider.Model = "" }, "provider.model"},
		{"missing base_url", func(p *Profile) { p.Provider.BaseURL = "" }, "provider.base_url"},
		{"missing api_key_env", func(p *Profile) { p.Provider.APIKeyEnv = "" }, "provider.api_key_env"},
		{"negative pricing", func(p *Profile) { p.Pricing.InputUSDPerMTok = -1 }, "pricing"},
		{"zero max_output", func(p *Profile) { p.Limits.MaxOutputTokens = 0 }, "max_output_tokens"},
		{"zero context", func(p *Profile) { p.Limits.ContextTokens = 0 }, "context_tokens"},
		{"missing resolved_at", func(p *Profile) { p.Versioning.ResolvedAt = "" }, "resolved_at"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			p := goodProfile()
			tc.mutate(&p)
			err := p.Validate()
			require.Error(t, err)
			require.Contains(t, err.Error(), tc.wantSub)
		})
	}
}

